  ClassicLecture(seq: 419, name: '妇人杂病·问曰:妇人病。飮食如故，烦热不得卧，而反倚息者何…', asset: 'assets/jingui/clause_440.md'),
  ClassicLecture(seq: 420, name: '妇人杂病·妇人阴寒，温阴中，坐药，蛇床子散主之。', asset: 'assets/jingui/clause_442.md'),
  ClassicLecture(seq: 421, name: '妇人杂病·少阴脉滑而数者，阴中即生疮，阴中蚀，疮烂者，狼牙…', asset: 'assets/jingui/clause_443.md'),
  ClassicLecture(seq: 422, name: '妇人杂病·胃气下泄，阴吹而正喧，此谷气之实也，膏髪煎主之。', asset: 'assets/jingui/clause_444.md'),
  ClassicLecture(seq: 423, name: '阴阳易差后劳复·概述', asset: 'assets/jingui/clause_445.md'),
  ClassicLecture(seq: 424, name: '阴阳易差后劳复·伤寒，阴阳易之为病，其人身体重，少气，少腹里急，…', asset: 'assets/jingui/clause_446.md'),
  ClassicLecture(seq: 425, name: '阴阳易差后劳复·大病差后，劳复者，枳实栀子豉汤主之。', asset: 'assets/jingui/clause_447.md'),
  ClassicLecture(seq: 426, name: '阴阳易差后劳复·伤寒脉浮者，以汗解之，脉沉实者，以下解之。差已后…', asset: 'assets/jingui/clause_448.md'),
  ClassicLecture(seq: 427, name: '阴阳易差后劳复·大病差后，从腰以下有水气者，牡蛎泽泻散主之。', asset: 'assets/jingui/clause_449.md'),
  ClassicLecture(seq: 428, name: '阴阳易差后劳复·大病差复，喜唾久不了了，胃上有寒，当以丸药温之，…', asset: 'assets/jingui/clause_450.md'),
  ClassicLecture(seq: 429, name: '阴阳易差后劳复·伤寒解后，虚羸少气，气逆欲吐，竹叶石膏汤主之。', asset: 'assets/jingui/clause_451.md'),
  ClassicLecture(seq: 430, name: '阴阳易差后劳复·病人脉已解，而曰暮微烦，以病新差，人强舆谷，脾胃…', asset: 'assets/jingui/clause_452.md'),
  ClassicLecture(seq: 431, name: '呕吐哕下利病·气利，诃黎勒散主之。', asset: 'assets/jingui/clause_453.md'),
  ClassicLecture(seq: 432, name: '水气病·气分，心下坚大如盘，桂枝去芍药加麻辛附子汤主之', asset: 'assets/jingui/clause_454.md'),
];
